def main():
    parser = argparse.ArgumentParser(description="Apply Dark Folklore 0.3 Occult Investigation source changes")
    parser.add_argument("--root", default=".", help="repository root (default: current directory)")
    parser.add_argument("--dry-run", action="store_true")
    args = parser.parse_args()
    root = Path(args.root).resolve()

    failures = []
    prepared = {}

    for rel, operations in REPLACEMENTS.items():
        path = root / rel
        if not path.is_file():
            failures.append(f"missing base file: {rel}")
            continue
        text = path.read_text(encoding="utf-8")
        original = text
        for old, new, desc in operations:
            count = text.count(old)
            if count != 1:
                failures.append(f"{rel}: expected exactly one context for '{desc}', found {count}")
                continue
            text = text.replace(old, new, 1)
        prepared[rel] = text
        if text == original:
            failures.append(f"{rel}: no effective changes were prepared")

    for rel, content in NEW_FILES.items():
        path = root / rel
        if path.exists():
            current = path.read_text(encoding="utf-8")
            if current != content:
                failures.append(f"new file already exists with different content: {rel}")

    if failures:
        print("REFUSING TO APPLY: repository no longer matches the audited 0.2 base.", file=sys.stderr)
        for failure in failures:
            print(" - " + failure, file=sys.stderr)
        return 2

    print(f"Validated {sum(len(v) for v in REPLACEMENTS.values())} replacements and {len(NEW_FILES)} new files.")
    if args.dry_run:
        print("Dry run only; nothing written.")
        return 0

    for rel, text in prepared.items():
        path = root / rel
        path.write_text(text, encoding="utf-8", newline="\n")
        print("updated", rel)

    for rel, content in NEW_FILES.items():
        path = root / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8", newline="\n")
        print("created", rel)

    print()
    print("Dark Folklore source is now staged as 0.3.0.")
    print(r"Run: .\gradlew.bat clean build --no-daemon --no-configuration-cache")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
